 ('agents.report.returned_no_reply', 'en', 'Returned to the supplier, no corrected invoice yet'),
 ('agents.report.returned_no_reply', 'de', 'An den Lieferanten zurückgesandt, noch keine korrigierte Rechnung'),
 ('agents.reporthint.returned_no_reply', 'en', 'Invoices returned to their supplier more than the days chosen ago, in the last 90 days, with no later invoice of the same number from them.'),
 ('agents.reporthint.returned_no_reply', 'de', 'Rechnungen, die vor mehr als den gewählten Tagen in den letzten 90 Tagen an den Lieferanten zurückgingen und zu denen keine spätere Rechnung mit derselben Nummer kam.'),
 ('agents.col.returned', 'en', 'Returned'),
 ('agents.col.returned', 'de', 'Zurückgesandt'),
 ('agents.col.dayssince', 'en', 'Days since'),
 ('agents.col.dayssince', 'de', 'Tage seither'),
 ('agents.col.returnreason', 'en', 'Why returned'),
 ('agents.col.returnreason', 'de', 'Grund der Rücksendung'),
